 protocol=dict(registered_utc=datetime.now(timezone.utc).isoformat(),hypothesis='Initial100-burn/400-draw sweeps failed mixing; increase warmup and draw count at the predefined central sigma, then check every path rather than only20 entries.',panel='D12_I405_N',split='validation',seed=SEED,chains=4,burn_sweeps=1000,sample_sweeps=2000,sigma_multiplier=1.,target='Same count-conditioned nonnegative Gaussian centered at released weak prior; no mean or model alteration.',kernel='Same75%adjacent/25%uniform independent triangle directions and exact truncated-normal updates as pilot.',diagnostic_gate='Raw split-Rhat<1.05 and approximate autocorrelation ESS>=100 on every path and total/priorL1/logdensity diagnostics. No ranking if any gate fails.',selection='Central sigma selected before results as default, not the easiest-converging sigma2. No hidden score or posterior decision ranking performed in this run.',source_sha256=d.sha(__file__),sampler_source_sha256=d.sha(d.WORK/'task4_gaussian_posterior_pilot.py'),initial_failure_sha256=d.sha(d.OUT/'task4_gaussian_posterior_pilot/diagnostics.json'),scope='Single-panel convergence study only. Gaussian error remains an unproved assumption; better mixing cannot establish true OD recovery. Official baseline unchanged, no Kaggle upload.')
 d.save(O/'protocol.json',protocol);paths,Q,c,b,hashes=base.load(protocol['panel'],protocol['split']);oi=paths.origin_zone.str.extract(r'^Z(\d+)$',expand=False).astype(int).to_numpy();di=paths.destination_zone.str.extract(r'^Z(\d+)$',expand=False).astype(int).to_numpy();nnode=int(max(di))+1;lookup=np.full((nnode,nnode),-1,int);lookup[oi,di]=np.arange(len(paths));triples=np.array(list(itertools.combinations(range(nnode),3)));assert len(paths)==nnode*(nnode-1)//2;assert np.max(np.abs(Q[:,lookup[triples[:,0],triples[:,2]]]-Q[:,lookup[triples[:,0],triples[:,1]]]-Q[:,lookup[triples[:,1],triples[:,2]]]))==0;_,R,piv=qr(Q.T,mode='economic',pivoting=True);rank=int((np.abs(np.diag(R))>max(abs(R[0,0]),1)*1e-10).sum());idx=piv[:rank];covfile=d.OUT/'task4_covariance_audit/full_train_frozen_models.json';cov=json.loads(covfile.read_text())['models']['path_additive'];loaded=(Q@b)[idx];sigma=np.sqrt(cov['variance'])*float(np.median(loaded[loaded>0]))/np.sqrt(np.mean(np.sum(Q[idx]**2,axis=1)));d.save(O/'input_sha256.json',dict(files=hashes,covariance_sha256=d.sha(covfile),sigma=sigma,triangle_identities_checked=len(triples)));pilot.SEED=SEED
 draws,summary=pilot.sample(Q,c,b,lookup,triples,sigma,1.,protocol);rows=[]
