 allpaths=pd.DataFrame(rows);allpaths.to_csv(O/'all_path_diagnostics.csv',index=False);summary['all_path_max_Rhat']=float(allpaths.raw_split_Rhat.max());summary['all_path_min_ESS']=float(allpaths.approximate_ESS.min());summary['paths_failing_Rhat']=int((allpaths.raw_split_Rhat>=1.05).sum());summary['paths_failing_ESS']=int((allpaths.approximate_ESS<100).sum());summary['ranking_eligible']=bool(summary['ranking_eligible'] and summary['all_path_max_Rhat']<1.05 and summary['all_path_min_ESS']>=100);summary['posterior_scores_evaluated']=False;out=d.WORK/'task4_posterior_longrun_samples/sigma1.npz';out.parent.mkdir(parents=True,exist_ok=True);np.savez_compressed(out,samples=draws);summary['samples_sha256']=d.sha(out);d.save(O/'diagnostics.json',summary);d.state(status='stage_complete',stage='task4_posterior_longrun_complete',next='Assess all-path and global mixing before any posterior risk calculation; do not relax thresholds to obtain a pass. Keep failures and official Task4 baseline, no Kaggle upload.');print('LONGRUN COMPLETE',summary['ranking_eligible'],summary['all_path_max_Rhat'],summary['all_path_min_ESS'],flush=True)

